import java.awt.*;import java.nio.file.*;import java.io.*;import java.util.*;import javax.swing.*;
public class App{
 static Set<String>tags(String text){Set<String>out=new TreeSet<>();for(String s:text.toLowerCase(Locale.ROOT).split(","))if(!s.isBlank())out.add(s.trim());if(out.size()>30)throw new IllegalArgumentException("At most 30 tags");return out;}
 static Properties encode(Map<String,Set<String>>data){if(data.size()>5000)throw new IllegalArgumentException("At most 5000 records");Properties p=new Properties();for(var e:data.entrySet())p.setProperty(Base64.getEncoder().encodeToString(e.getKey().getBytes(java.nio.charset.StandardCharsets.UTF_8)),String.join(",",e.getValue()));return p;}
 static Map<String,Set<String>>decode(Properties p){Map<String,Set<String>>out=new TreeMap<>();for(String key:p.stringPropertyNames())out.put(new String(Base64.getDecoder().decode(key),java.nio.charset.StandardCharsets.UTF_8),tags(p.getProperty(key)));encode(out);return out;}
 public static void main(String[]args){if(args.length>0&&args[0].equals("--self-test")){var data=Map.of("/tmp/a file",tags(" Work,work, READ "));if(!decode(encode(data)).equals(data)||data.values().iterator().next().size()!=2)throw new AssertionError();System.out.println("Tag normalization and index round trip passed");return;}SwingUtilities.invokeLater(()->{JFrame f=new JFrame("File Tag Organizer");f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setSize(1000,650);JPanel root=new JPanel(new BorderLayout(10,10));root.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));f.setContentPane(root);Map<String,Set<String>>data=new TreeMap<>();JTextField query=new JTextField(20),input=new JTextField(25);JPanel top=new JPanel();top.add(new JLabel("AND filter tags"));top.add(query);top.add(new JLabel("Tags for added file"));top.add(input);root.add(top,BorderLayout.NORTH);JList<String>list=new JList<>();DefaultListModel<String>model=new DefaultListModel<>();list.setModel(model);root.add(new JScrollPane(list),BorderLayout.CENTER);java.util.List<String>visible=new ArrayList<>();Runnable draw=()->{model.clear();visible.clear();Set<String>needed=tags(query.getText());for(var e:data.entrySet())if(e.getValue().containsAll(needed)){visible.add(e.getKey());model.addElement((Files.exists(Path.of(e.getKey()))?"":"MISSING ")+e.getKey()+"  ["+String.join(", ",e.getValue())+"]");}};JPanel controls=new JPanel();root.add(controls,BorderLayout.SOUTH);java.util.function.BiConsumer<String,Runnable>button=(text,fn)->{JButton b=new JButton(text);controls.add(b);b.addActionListener(e->{try{fn.run();draw.run();}catch(RuntimeException err){JOptionPane.showMessageDialog(f,err.getMessage());}});};button.accept("Add / retag file",()->{JFileChooser c=new JFileChooser();if(c.showOpenDialog(f)==JFileChooser.APPROVE_OPTION){data.put(c.getSelectedFile().toPath().toAbsolutePath().toString(),tags(input.getText()));encode(data);}});button.accept("Filter",()->{});button.accept("Remove index entry",()->{if(list.getSelectedIndex()>=0)data.remove(visible.get(list.getSelectedIndex()));});button.accept("Save index",()->{JFileChooser c=new JFileChooser();if(c.showSaveDialog(f)==JFileChooser.APPROVE_OPTION)try(Writer out=Files.newBufferedWriter(c.getSelectedFile().toPath())){encode(data).store(out,"Local file tag index");}catch(IOException e){throw new IllegalStateException(e);}});button.accept("Open index",()->{JFileChooser c=new JFileChooser();if(c.showOpenDialog(f)==JFileChooser.APPROVE_OPTION)try(Reader in=Files.newBufferedReader(c.getSelectedFile().toPath())){Properties p=new Properties();p.load(in);var next=decode(p);data.clear();data.putAll(next);}catch(IOException e){throw new IllegalStateException(e);}});draw.run();f.setLocationRelativeTo(null);f.setVisible(true);});}
}
